select count(*) teams, count(*) filter (where n<18) under18, min(n) minn, round(min(avg_toi),2) min_avg, round(max(avg_toi),2) max_avg, round(max(max_toi),2) max_player_toi from (select run_id, game_id, team_id, count(*) n, avg(proj_toi_es_seconds+proj_toi_pp_seconds+proj_toi_pk_seconds)/60.0 avg_toi, max(proj_toi_es_seconds+proj_toi_pp_seconds+proj_toi_pk_seconds)/60.0 max_toi from forge_player_projections where run_id in (select run_id from forge_runs where created_at::date='2026-11-13' and metrics->'execution_scope'->>'mode'='full_slate') group by 1,2,3) x
